      "Details": "สามารถดำเนินการได้ โดยจะต้องเสนอขอกำหนดตำแหน่งทางวิชาการ โดยวิธีพิเศษ มีหลักเกณฑ์ ดังนี้\n- เสนอด้วยวิธีที่ 1 ของวิธีการปกติเท่านั้น โดยแต่งตั้งคณะอนุกรรมการประเมินผลงานทางวิชาการ จำนวน 5 ท่าน \n- ตำแหน่งผู้ช่วยศาสตราจารย์และรองศาสตราจารย์ ผลงานต้องมีคุณภาพในระดับดีมาก 3 ใน 5\n- ตำแหน่งศาสตราจารย์ ผลงานต้องมีคุณภาพในระดับดีเด่น 4 ใน 5)\n\nทั้งนี้ ผลงานทางวิชาการที่เสนอขอจะต้องสอดคล้องหรือเกี่ยวข้องกับสาขาวิชาที่เสนอขอ",
