      "Details": "ปัจจุบันมีระยะเวลาการดำเนินการ ประมาณ 6 - 7 เดือน (นับจากวันที่กองทรัพยากรมนุษย์รับเรื่อง)\n(กรณีที่ไม่ได้ส่งกลับคณะเพื่อแก้ไขเอกสาร ไม่ได้จัดให้มีการประชุมคณะอนุกรรมการประเมินผลงานทางวิชาการ หรือประเด็นอื่น ๆ ที่ต้องชี้แจงหรือดำเนินการเพิ่มเติม)\n\nทั้งนี้ ขึ้นอยู่กับระดับตำแหน่งทางวิชาการและจำนวนผลงานทางวิชาการที่เสนอขอด้วย หากเสนอตำรา หนังสือ หรือผลงานหลายเรื่อง ผู้ทรงคุณวุฒิจะใช้เวลาในการพิจารณามากขึ้น",
