      "Title": "การประเมินการสอน หมายถึงอะไร ต้องทำอะไรบ้าง ต้องทำทุกหัวข้อหรือไม่ หรือทำเฉพาะหัวข้อที่มีการสอบสอน",
      "Details": "1. การประเมินคุณภาพการสอนของผู้ขอระดับตำแหน่งผู้ช่วยศาสตราจารย์และรองศาสตราจารย์ ที่ครอบคลุมข้อมูลที่จำเป็นทุก ๆ ด้าน โดยเฉพาะความสามารถในการถ่ายทอดความรู้ เพื่อช่วยให้ผู้เรียนได้เกิดการเรียนรู้ สามารถประเมินการเรียนรู้ได้ผลถูกต้องที่สุด และสอดคล้องกับผลลัพธ์การเรียนรู้ที่คาดหวัง \n2. พนักงานมหาวิทยาลัย ประเมินการสอนก่อนยื่นเสนอขอกำหนดตำแหน่งทางวิชาการ\n3. ข้าราชการฯ ประเมินการสอนพร้อมยื่นเสนอขอกำหนดตำแหน่งทางวิชาการ\n\nสิ่งที่ต้องยื่นประเมินการสอน\n1. รายวิชาของผู้ขอซึ่งเทียบค่าได้ไม่น้อยกว่า 3 หน่วยกิตระบบทวิภาคหรือ 45 ชั่วโมงบรรยาย\n2. ประเมินการสอนรายวิชาที่ผู้ขอยื่น ตามองค์ประกอบการประเมินผลการสอน 9 ข้อ รวม 100 คะแนน\n   - ผู้ช่วยศาสตราจารย์ 60 คะแนนขึ้นไป (ระดับชำนาญ)\n   - รองศาสตราจารย์ 80 คะแนนขึ้นไป (ระดับชำนาญพิเศษ)\n3. เสนอเอกสารหลักฐานทุกหัวข้อที่ทำการสอนในรายวิชาที่เสนอประเมินการสอน โดย\n   - แบบที่ 1 เอกสารประกอบการสอน หรือ\n   - แบบที่ 2 เอกสารคําสอน\nคุณภาพเป็นไปตามเกณฑ์ 4 ข้อแรก (ไม่ต่ำกว่าระดับดี)",
      "Date": "2026-03-22",
      "Link": "http://bit.ly/4pANqY6",
