      "Title": "การเตรียมตัวเสนอขอกำหนดตำแหน่งทางวิชาการ",
      "Details": "1. พนักงานมหาวิทยาลัยต้องมีผลการประเมินการสอนก่อนเสนอขอกำหนดตำแหน่งทางวิชาการ (ผลการประเมินมีอายุ 2 ปีนับจากวันที่ ก.พ.ว. เห็นชอบผลการประเมิน) / ข้าราชการฯ ประเมินการสอนพร้อมเสนอขอกำหนดตำแหน่งทางวิชาการ\n2. ต้องมีคุณสมบัติครบถ้วนตามตำแหน่งที่จะเสนอขอ\n3. มีจำนวนผลงานทางวิชาการตามระดับตำแหน่งที่เสนอขอ โดยผลงานทางวิชาการต้องเป็นไปตามคำนิยามและได้รับการเผยแพร่ตามหลักเกณฑ์ที่กำหนด \n   - พนักงานมหาวิทยาลัยบังคับใช้ตามข้อบังคับ มศก. พ.ศ. 2561 และฉบับที่แก้ไขเพิ่มเติม\n   - ข้าราชการฯ บังคับใช้ตามประกาศ ก.พ.อ.ฯ พ.ศ. 2564 และฉบับที่แก้ไขเพิ่มเติม",
      "Date": "2026-03-22",
