      "Details": "1. ผลงานวิจัย สามารถนำมาใช้เสนอขอกำหนดตำแหน่งทางวิชาการได้ ทั้งนี้ ต้องทำในฐานะอาจารย์ประจำ และต้องแนบหนังสือรับรองการทำงานจากต้นสังกัดเดิมด้วย\n\n2. รายวิชาที่จะประเมินการสอนและเอกสารหลักฐานที่ใช้ในการประเมินผลการสอน ต้องเป็นวิชาใดวิชาหนึ่งตามหลักสูตรของมหาวิทยาลัยศิลปากรที่สภามหาวิทยาลัยศิลปากรกำหนด และใช้สอนมาแล้วไม่เกิน 3 ปีการศึกษา",
